import urllib.request
import urllib.error
import json
import ssl
from typing import Optional, Dict, Any

_API_URL = \"https://api.openai.com/v1/responses\"


class OpenAIResponseError(Exception):
    pass


def _build_request_body(model: str, input_text: str, instructions: Optional[str] = None, tools: Optional[list] = None, extra_body: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    body: Dict[str, Any] = {\"model\": model, \"input\": input_text}
    if instructions is not None:
        body[\"instructions\"] = instructions
    if tools is not None:
        body[\"tools\"] = tools
    if extra_body is not None:
        body.update(extra_body)
    return body


def _send_request(body: Dict[str, Any], api_key: str, timeout: float = 30.0) -> Dict[str, Any]:
    data = json.dumps(body).encode(\"utf-8\")
    req = urllib.request.Request(
        _API_URL,
        data=data,
        method=\"POST\",
        headers={
            \"Authorization\": \"Bearer \" + api_key,
            \"Content-Type\": \"application/json\",
            \"OpenAI-Beta\": \"responses=v1\",
        },
    )
    context = ssl.create_default_context()
    try:
        with urllib.request.urlopen(req, timeout=timeout, context=context) as response:
            if response.status == 200:
                return json.loads(response.read().decode(\"utf-8\"))
            else:
                raise OpenAIResponseError(\"Unexpected HTTP status: %d\" % response.status)
    except urllib.error.HTTPError as e:
        error_body_raw = e.read().decode(\"utf-8\")
        try:
            error_json = json.loads(error_body_raw)
            error_message = error_json.get(\"error\", {}).get(\"message\", error_body_raw)
        except json.JSONDecodeError:
            error_message = error_body_raw
        raise OpenAIResponseError(\"HTTP %d: %s\" % (e.code, error_message)) from e
    except urllib.error.URLError as e:
        raise OpenAIResponseError(\"Connection error: %s\" % e.reason) from e


def send_prompt(api_key: str, model: str, input_text: str, instructions: Optional[str] = None, tools: Optional[list] = None, extra_body: Optional[Dict[str, Any]] = None, timeout: float = 30.0) -> Dict[str, Any]:
    body = _build_request_body(model=model, input_text=input_text, instructions=instructions, tools=tools, extra_body=extra_body)
    return _send_request(body, api_key, timeout)


def get_text_response(api_key: str, model: str, input_text: str, instructions: Optional[str] = None, tools: Optional[list] = None, extra_body: Optional[Dict[str, Any]] = None, timeout: float = 30.0) -> str:
    response = send_prompt(api_key=[REDACTED_SECRET] model=model, input_text=input_text, instructions=instructions, tools=tools, extra_body=extra_body, timeout=timeout)
    outputs = response.get(\"output\", [])
    if not outputs:
        raise IndexError(\"Response contains no output items.\")
    first_output = outputs[0]
    text = first_output.get(\"content\", [{}])[0].get(\"text\", \"\")
    return text
PYEOF"

